     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.messages.EmailSender;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.math.BigDecimal;
     8	
     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final EmailSender emailSender;
    18	
    19	    public ReservationService(
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    21	        this.rooms = rooms;
    22	        this.store = store;
    23	        this.priceCalculator = priceCalculator;
    24	        this.emailSender = emailSender;
    25	    }
    26	
    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        if (request.children() < 0) {
    35	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the number of children cannot be negative");
    36	        }
    37	        Room room = rooms.find(request.roomNumber())
    38	                .orElseThrow(() -> new HotelException(
    39	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    40	        if (request.guests() + request.children() > room.capacity()) {
    41	            throw new HotelException(
    42	                    ErrorCode.CAPACITY_EXCEEDED,
    43	                    "room " + room.number() + " takes at most " + room.capacity() + " people, children included");
    44	        }
    45	        boolean roomTaken = store.all().stream()
    46	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    47	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    48	        if (roomTaken) {
    49	            throw new HotelException(
    50	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    51	        }
    52	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    53	        Reservation reservation = new Reservation(store.nextId(), request, price);
    54	        store.save(reservation);
    55	        return reservation;
    56	    }
    57	
    58	    public Reservation find(long reservationId) {
    59	        return store.find(reservationId)
    60	                .orElseThrow(() -> new HotelException(
    61	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    62	    }
    63	
    64	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    65	    public synchronized Reservation confirm(long reservationId) {
    66	        Reservation reservation = find(reservationId);
    67	        if (reservation.status() != ReservationStatus.PENDING) {
    68	            throw notAllowed(reservation, "confirm");
    69	        }
    70	        reservation.confirmPayment();
    71	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    72	        emailSender.send(
    73	                reservation.guest().email(),
    74	                "Reserva confirmada - " + HOTEL_NAME,
    75	                confirmationEmailBody(reservation, receipt));
    76	        return reservation;
    77	    }
    78	
    79	    /**
    80	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    81	     * reservation was never paid, so nothing comes back).
    82	     */
    83	    public synchronized Reservation cancel(long reservationId) {
    84	        Reservation reservation = find(reservationId);
    85	        if (reservation.status() != ReservationStatus.PENDING
    86	                && reservation.status() != ReservationStatus.CONFIRMED) {
    87	            throw notAllowed(reservation, "cancel");
    88	        }
    89	        BigDecimal refund = switch (reservation.ratePlan()) {
    90	            case STANDARD -> reservation.amountPaid();
    91	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    92	        };
    93	        reservation.cancel(refund);
    94	        return reservation;
    95	    }
    96	
    97	    public synchronized Reservation checkIn(long reservationId) {
    98	        Reservation reservation = find(reservationId);
    99	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   100	            throw notAllowed(reservation, "check in");
   101	        }
   102	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   103	        return reservation;
   104	    }
   105	
   106	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
