320	     8	
321	     9	/**
322	    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
323	    11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
324	    12	 * (half-even) at every step.
325	    13	 */
326	    14	public final class PriceCalculator {
327	    15	
328	    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
329	    17	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
330	    18	
331	    19	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
332	    20	        int nights = 0;
333	    21	        BigDecimal subtotal = cents(BigDecimal.ZERO);
334	    22	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
335	    23	            subtotal = subtotal.add(nightPrice(room, night));
336	    24	            nights++;
337	    25	        }
338	    26	        BigDecimal discount = switch (ratePlan) {
339	    27	            case STANDARD -> cents(BigDecimal.ZERO);
340	    28	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
341	    29	        };
342	    30	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
343	    31	    }
344	    32	
345	    33	    BigDecimal nightPrice(Room room, LocalDate night) {
346	    34	        BigDecimal nightlyRate = room.nightlyRate();
347	    35	        if (isHighSeason(night)) {
348	    36	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
349	    37	        }
350	    38	        return cents(nightlyRate);
351	    39	    }
352	    40	
353	    41	    /** High season: from December 15 to the end of February, and the whole of July. */
354	    42	    static boolean isHighSeason(LocalDate date) {
355	    43	        Month month = date.getMonth();
356	    44	        return month == Month.JANUARY
357	    45	                || month == Month.FEBRUARY
358	    46	                || month == Month.JULY
359	    47	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
360	    48	    }
361	    49	
362	    50	    static BigDecimal cents(BigDecimal value) {
363	    51	        return value.setScale(2, RoundingMode.HALF_EVEN);
364	    52	    }
365	    53	}
